import React, { useState, useEffect } from 'react';
import { Save, X, Plus } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const ProfilePage = () => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [profileData, setProfileData] = useState({ fullName: '', bio: '', github: '', portfolio: '' });
  const [skills, setSkills] = useState(['React', 'Node.js']);
  const [newSkill, setNewSkill] = useState('');

  useEffect(() => {
    const fetchData = async () => {
      const token = localStorage.getItem('token');
      if (!token) { navigate('/'); return; }
      try {
        // تم استخدام الـ backticks هنا بشكل صحيح 
        const res = await axios.get('http://127.0.0.1:8000/api/profile/', {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (res.data) {
          setProfileData({
            fullName: res.data.user?.username || '',
            bio: res.data.bio || '',
            github: res.data.github || '',
            portfolio: res.data.portfolio || ''
          });
        }
      } catch (err) {
        console.error("Error fetching data:", err);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, [navigate]);

  if (isLoading) return <div>Loading Profile...</div>;

  return (
    <div style={{ padding: '20px', backgroundColor: '#fdfbff', minHeight: '100vh' }}>
      <div style={{ maxWidth: '800px', margin: '0 auto', background: 'white', padding: '30px', borderRadius: '15px' }}>
        <h2>Digital CV Settings</h2>
        <div style={{ marginBottom: '15px' }}>
          <label>Full Name</label>
          <input 
            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
            value={profileData.fullName} 
            onChange={(e) => setProfileData({...profileData, fullName: e.target.value})} 
          />
        </div>
        <div style={{ marginBottom: '15px' }}>
          <label>GitHub URL</label>
          <input 
            style={{ width: '100%', padding: '10px', marginTop: '5px' }}
            value={profileData.github} 
            onChange={(e) => setProfileData({...profileData, github: e.target.value})} 
          />
        </div>
        <button style={{ background: '#4a3f6b', color: 'white', padding: '12px 25px', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>
          <Save size={18} style={{ marginRight: '8px' }} /> Save Digital CV
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
